window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-75b0bd99132c53ed"]={"versions": [{"id": "FIG-75b0bd99132c53ed", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Adaptive Platform Timing Extensions (TPS AdaptivePlatformTimingExtensions). Das Diagramm spezifiziert die Metamodellstruktur zur Definition von Burst-Muster-Ereignisauslösebedingungen (<code>BurstPatternEventTriggering</code>) innerhalb des Pakets bzw. Namensraums <code>EventTriggeringConstraint</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei Klassen mit ihren Attributen und Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>EventTriggeringConstraint::BurstPatternEventTriggering</code></strong> (gekennzeichnet mit dem Kontext <code>EventTriggeringConstraint</code> oben rechts):\n<ul class=\"fig-list\"><li><code>+ maxNumberOfOccurrences: PositiveInteger</code> (Multiplizität 1)\n</li><li><code>+ minNumberOfOccurrences: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><strong><code>MultidimensionalTime::MultidimensionalTime</code></strong>:\n<ul class=\"fig-list\"><li><code>+ cseCode: CseCodeType</code> (Multiplizität 1)\n</li><li><code>+ cseCodeFactor: Integer</code> (Multiplizität 1)\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Assoziationen (Kompositionen, ausgehend von <code>BurstPatternEventTriggering</code> mit ausgefüllter Raute hin zu <code>MultidimensionalTime</code>):</p>\n<ul class=\"fig-list\"><li><code>+patternLength</code>: Multiplizität <code>1</code>\n</li><li><code>+minimumInterArrivalTime</code>: Multiplizität <code>1</code>\n</li><li><code>+patternPeriod</code>: Multiplizität <code>0..1</code>\n</li><li><code>+patternJitter</code>: Multiplizität <code>0..1</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es definiert die zeitlichen und quantitativen Parameter für Ereignisbündelungen (Bursts):</p>\n<ul class=\"fig-list\"><li>Ein Burst-Muster beschreibt das Auftreten von Ereignissen innerhalb eines Beobachtungsfensters (<code>patternLength</code>) mit einer Mindestabstandszeit zwischen Ereignissen (<code>minimumInterArrivalTime</code>).\n</li><li>Begrenzt wird das Auftreten durch <code>maxNumberOfOccurrences</code> sowie optional <code>minNumberOfOccurrences</code>.\n</li><li>Optional können ein Wiederholzyklus des Musters (<code>patternPeriod</code>) und zeitlicher Jitter (<code>patternJitter</code>) über Instanzen von <code>MultidimensionalTime</code> definiert werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Vorgabe für Timing-Constraint-Beschreibungen in AUTOSAR Adaptive.</p>\n<ul class=\"fig-list\"><li><code>maxNumberOfOccurrences</code>, <code>patternLength</code> und <code>minimumInterArrivalTime</code> sind Pflichtelemente (Multiplizität 1) zur eindeutigen Festlegung eines Burst-Musters.\n</li><li><code>minNumberOfOccurrences</code>, <code>patternPeriod</code> und <code>patternJitter</code> sind optional (Multiplizität <code>0..1</code>).\n</li><li>Zeitangaben referenzieren als Komposition jeweils ein <code>MultidimensionalTime</code>-Element mit obligatorischer Angabe von <code>cseCode</code> und <code>cseCodeFactor</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-17ebd69eff38afcb", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Adaptive Platform Timing Extensions (TPS AdaptivePlatformTimingExtensions). Das Diagramm spezifiziert die Metamodellstruktur zur Definition von Burst-Muster-Ereignisauslösebedingungen (<code>BurstPatternEventTriggering</code>) im Kontext <code>EventTriggeringConstraint</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei Klassen mit ihren Attributen und Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>BurstPatternEventTriggering</code></strong> (gekennzeichnet mit dem Paketkontext <code>EventTriggeringConstraint</code> oben rechts):\n<ul class=\"fig-list\"><li><code>+ maxNumberOfOccurrences: PositiveInteger</code> (Multiplizität 1)\n</li><li><code>+ minNumberOfOccurrences: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><strong><code>MultidimensionalTime</code></strong>:\n<ul class=\"fig-list\"><li><code>+ cseCode: CseCodeType</code> (Multiplizität 1)\n</li><li><code>+ cseCodeFactor: Integer</code> (Multiplizität 1)\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Assoziationen (Kompositionen, ausgehend von <code>BurstPatternEventTriggering</code> mit ausgefüllter Raute hin zu <code>MultidimensionalTime</code>):</p>\n<ul class=\"fig-list\"><li><code>+patternLength</code>: Multiplizität <code>1</code>\n</li><li><code>+minimumInterArrivalTime</code>: Multiplizität <code>1</code>\n</li><li><code>+patternPeriod</code>: Multiplizität <code>0..1</code>\n</li><li><code>+patternJitter</code>: Multiplizität <code>0..1</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es definiert die zeitlichen und quantitativen Parameter für Ereignisbündelungen (Bursts):</p>\n<ul class=\"fig-list\"><li>Ein Burst-Muster beschreibt das Auftreten von Ereignissen innerhalb eines Beobachtungsfensters (<code>patternLength</code>) mit einer Mindestabstandszeit zwischen Ereignissen (<code>minimumInterArrivalTime</code>).\n</li><li>Begrenzt wird das Auftreten durch <code>maxNumberOfOccurrences</code> sowie optional <code>minNumberOfOccurrences</code>.\n</li><li>Optional können ein Wiederholzyklus des Musters (<code>patternPeriod</code>) und zeitlicher Jitter (<code>patternJitter</code>) über Instanzen von <code>MultidimensionalTime</code> definiert werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Vorgabe für Timing-Constraint-Beschreibungen in AUTOSAR Adaptive.</p>\n<ul class=\"fig-list\"><li><code>maxNumberOfOccurrences</code>, <code>patternLength</code> und <code>minimumInterArrivalTime</code> sind Pflichtelemente (Multiplizität 1) zur eindeutigen Festlegung eines Burst-Musters.\n</li><li><code>minNumberOfOccurrences</code>, <code>patternPeriod</code> und <code>patternJitter</code> sind optional (Multiplizität <code>0..1</code>).\n</li><li>Zeitangaben referenzieren als Komposition jeweils ein <code>MultidimensionalTime</code>-Element mit obligatorischer Angabe von <code>cseCode</code> und <code>cseCodeFactor</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f9f47c38fff86dec", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Adaptive Platform Timing Extensions (TPS AdaptivePlatformTimingExtensions). Das Diagramm spezifiziert die Metamodellstruktur zur Definition von Burst-Muster-Ereignisauslösebedingungen (<code>BurstPatternEventTriggering</code>) im Kontext <code>EventTriggeringConstraint</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei Klassen mit ihren Attributen und Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>BurstPatternEventTriggering</code></strong> (gekennzeichnet mit dem Paketkontext <code>EventTriggeringConstraint</code> oben rechts):\n<ul class=\"fig-list\"><li><code>+ maxNumberOfOccurrences: PositiveInteger [0..1]</code>\n</li><li><code>+ minNumberOfOccurrences: PositiveInteger [0..1]</code>\n</li></ul>\n</li><li><strong><code>MultidimensionalTime</code></strong>:\n<ul class=\"fig-list\"><li><code>+ cseCode: CseCodeType [0..1]</code>\n</li><li><code>+ cseCodeFactor: Integer [0..1]</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Assoziationen (Kompositionen, ausgehend von <code>BurstPatternEventTriggering</code> mit ausgefüllter Raute hin zu <code>MultidimensionalTime</code>):</p>\n<ul class=\"fig-list\"><li><code>+patternLength</code>: Multiplizität <code>0..1</code>\n</li><li><code>+minimumInterArrivalTime</code>: Multiplizität <code>0..1</code>\n</li><li><code>+patternPeriod</code>: Multiplizität <code>0..1</code>\n</li><li><code>+patternJitter</code>: Multiplizität <code>0..1</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es definiert die zeitlichen und quantitativen Parameter für Ereignisbündelungen (Bursts):</p>\n<ul class=\"fig-list\"><li>Ein Burst-Muster beschreibt das Auftreten von Ereignissen innerhalb eines Beobachtungsfensters (<code>patternLength</code>) mit einer Mindestabstandszeit zwischen Ereignissen (<code>minimumInterArrivalTime</code>).\n</li><li>Begrenzt wird das Auftreten durch <code>maxNumberOfOccurrences</code> sowie optional <code>minNumberOfOccurrences</code>.\n</li><li>Optional können ein Wiederholzyklus des Musters (<code>patternPeriod</code>) und zeitlicher Jitter (<code>patternJitter</code>) über Instanzen von <code>MultidimensionalTime</code> definiert werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Vorgabe für Timing-Constraint-Beschreibungen in AUTOSAR Adaptive.</p>\n<ul class=\"fig-list\"><li>Sämtliche Attribute (<code>maxNumberOfOccurrences</code>, <code>minNumberOfOccurrences</code>) und Zeitreferenzen (<code>patternLength</code>, <code>minimumInterArrivalTime</code>, <code>patternPeriod</code>, <code>patternJitter</code>) besitzen die Multiplizität <code>0..1</code> und sind somit optional.\n</li><li>Innerhalb der Zielklasse <code>MultidimensionalTime</code> sind die Attribute <code>cseCode</code> und <code>cseCodeFactor</code> ebenfalls optional (<code>[0..1]</code>).\n</li><li>Bei Modellierung und Toolunterstützung müssen fehlende Werte für Zeitfenster oder maximale Auftretenshäufigkeiten über übergeordnete Randbedingungen oder Default-Semantiken abgesichert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-75b0bd99132c53ed", "to": "FIG-17ebd69eff38afcb", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Entfernung des Paketpräfixes <code>EventTriggeringConstraint::</code> vor dem Klassennamen <code>BurstPatternEventTriggering</code>.\n</li><li>Entfernung des Paketpräfixes <code>MultidimensionalTime::</code> vor dem Klassennamen <code>MultidimensionalTime</code>.\n</li><li>Leicht angepasste Platzierung der Assoziationsbeschriftungen.\n</li></ul>"}, {"from": "FIG-17ebd69eff38afcb", "to": "FIG-f9f47c38fff86dec", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Multiplizität des Attributs <code>maxNumberOfOccurrences</code> von <code>1</code> (implizit) auf <code>[0..1]</code> geändert.\n</li><li>Multiplizität des Attributs <code>cseCode</code> in <code>MultidimensionalTime</code> von <code>1</code> (implizit) auf <code>[0..1]</code> geändert.\n</li><li>Multiplizität des Attributs <code>cseCodeFactor</code> in <code>MultidimensionalTime</code> von <code>1</code> (implizit) auf <code>[0..1]</code> geändert.\n</li><li>Multiplizität der Kompositionsrolle <code>+patternLength</code> von <code>1</code> auf <code>0..1</code> geändert.\n</li><li>Multiplizität der Kompositionsrolle <code>+minimumInterArrivalTime</code> von <code>1</code> auf <code>0..1</code> geändert.\n</li></ul>"}]};
